 return '<div class="source" id="src-'+h(e['source_id'])+'"><b>'+h(e['source_id']+' '+e['publisher']+'｜'+e['title'])+'</b><br><small>発行日 '+h(e.get('published_date','未記載'))+'｜確認 '+h(e['checked_date'])+'｜'+h(e['verification'])+'</small><p><a href="'+h(e['url'])+'" target="_blank" rel="noopener">原典を開く</a>　掲載位置：'+h(e['locator'])+'</p>'+('<blockquote>原文：「'+h(e['short_quote'])+'」</blockquote>' if e['short_quote'] else '')+'<p><b>文脈の要約：</b>'+h(e['context_summary'])+'</p><p><b>留保：</b>'+h(e['not_evidence_for'])+'</p></div>'
