b='<section><h2>要旨</h2><p class="lead">'+h(g['thesis'])+'</p>'+metric+'<p class="alert">AI・フィジカルAIのタグ件数は、機能記載・呼称・基盤を含む候補数です。実装数、性能の優劣、普及率を表しません。</p><ul class="toc">'+''.join(f'<li><a href="#analysis-{n}">{n+1}. {h(a["title"])}</a></li>' for n,a in enumerate(g['analysis']))+'<li><a href="#comparison">タスク別技術比較</a></li><li><a href="#visits">訪問の組合せ</a></li><li><a href="#evidence">原文・根拠台帳</a></li></ul></section>'
