 b+=f'<section id="analysis-{n}"><h2>{n+1}. {h(a["title"])}</h2><p class="lead">{h(a["claim"])}</p><p><b>公開資料の要約：</b>{h(a["evidence"])} {refs(a["refs"])}</p><p class="summary"><b>調査者の分析：</b>{h(a["inference"])}</p><p><b>反例・留保：</b>{h(a["counter"])}</p></section>'
